    {
      "id": "reflection.feedback_days",
      "tiers": [
        {
          "id": "reflection.feedback_days:t1",
          "title": "Железо, к микрофону",
          "phrase": "Ты оставляешь обратную связь о подходах: таких дней уже 2. Железо молчит, а у тебя есть что сказать.",
          "imagePrompt": "A stubby-legged handheld microphone leans toward a small dumbbell perched on a folded gym towel, holding a tiny blank cue card; the dumbbell tilts one plate toward the microphone as if ready to answer.",
          "fishMarkup": "[warm] Ты оставляешь обратную связь о подходах: таких дней уже <emphasis>2</emphasis>. Железо молчит, а у тебя есть что сказать.",
          "audioText": "Ты оставляешь обратную связь о подходах: таких дней уже 2. Железо молчит, а у тебя есть что сказать."
        },
        {
          "id": "reflection.feedback_days:t2",
          "title": "Корреспондент между подходами",
          "phrase": "В твоей истории уже 8 дней с обратной связью о подходах. Ты не просто двигаешь железо — ты даёшь ему рецензию.",
          "imagePrompt": "A stubby-legged microphone reporter balances on a stack of weight plates, extending its cable arm toward a barbell at a tiny press table; several dumbbells lean in like curious reporters.",
          "fishMarkup": "[confident] В твоей истории уже <emphasis>8 дней</emphasis> с обратной связью о подходах. Ты не просто двигаешь железо — ты даёшь ему рецензию.",
          "audioText": "В твоей истории уже 8 дней с обратной связью о подходах. Ты не просто двигаешь железо — ты даёшь ему рецензию."
        },
        {
          "id": "reflection.feedback_days:t3",
          "title": "Штанга просит слова",
          "phrase": "Ты накопил 20 дней с обратной связью о подходах. Микрофон твой, а штанга на пресс-конференции просит вопрос полегче.",
          "imagePrompt": "A giant stubby-legged microphone hosts a grand press conference, leaning over a barbell hiding behind a towel; the barbell raises one plate like a timid hand while a crowd of dumbbells waits for its answer.",
          "fishMarkup": "[triumphant] Ты накопил <emphasis>20 дней</emphasis> с обратной связью о подходах. Микрофон твой, а штанга на пресс-конференции <slow>просит вопрос полегче</slow>.",
          "audioText": "Ты накопил 20 дней с обратной связью о подходах. Микрофон твой, а штанга на пресс-конференции просит вопрос полегче."
        }
      ]
    },
    {
      "id": "reflection.note_weeks",
      "tiers": [
        {
          "id": "reflection.note_weeks:t1",
          "title": "Раковина с полями",
          "phrase": "Ты оставил собственные заметки уже в 2 разных неделях. У твоих наблюдений появилось место на странице — пусть обживаются.",
          "imagePrompt": "A small snail carries a spiral notebook instead of a shell, gently tucking two loose blank pages under its cover with a feeler; a curled page corner forms a tiny ramp beside its trail.",
          "fishMarkup": "[warm] Ты оставил собственные заметки уже в <emphasis>2 разных неделях</emphasis>. У твоих наблюдений появилось место на странице — пусть обживаются.",
          "audioText": "Ты оставил собственные заметки уже в 2 разных неделях. У твоих наблюдений появилось место на странице — пусть обживаются."
        },
        {
          "id": "reflection.note_weeks:t2",
          "title": "Страницы едут дальше",
          "phrase": "Ты оставляешь свои заметки: в копилке уже 6 разных недель. Дневник вылез из раковины и присматривает себе полку.",
          "imagePrompt": "The notebook-shelled snail pulls a little cart piled with loose blank pages, using a ribbon bookmark as a towline; its feelers point toward an empty shelf that looks comically large beside it.",
          "fishMarkup": "[playful] Ты оставляешь свои заметки: в копилке уже <emphasis>6 разных недель</emphasis>. Дневник вылез из раковины и присматривает себе полку.",
          "audioText": "Ты оставляешь свои заметки: в копилке уже 6 разных недель. Дневник вылез из раковины и присматривает себе полку."
        },
        {
          "id": "reflection.note_weeks:t3",
          "title": "Архив на усиках",
          "phrase": "Свои заметки ты оставил уже в 12 разных неделях. Это личный архив: даже «сегодня было странно» здесь важнее чужих умных цитат.",
          "imagePrompt": "The notebook-shelled snail opens its cover into a rotating file rack, sorting curled blank pages with both feelers; a small desk lamp rides on top while a tidy fan of paper follows its trail.",
          "fishMarkup": "[confident] Свои заметки ты оставил уже в <emphasis>12 разных неделях</emphasis>. Это личный архив: даже «сегодня было странно» здесь важнее чужих умных цитат.",
          "audioText": "Свои заметки ты оставил уже в 12 разных неделях. Это личный архив: даже «сегодня было странно» здесь важнее чужих умных цитат."
        },
        {
          "id": "reflection.note_weeks:t4",
          "title": "Библиотека набирает ход",
          "phrase": "В твоём дневнике уже 26 разных недель с собственными заметками. Ты собрал столько наблюдений, что полка задумалась о расширении.",
          "imagePrompt": "The notebook-shelled snail carries a branching library of compact shelves, bridging a gap between them with an open blank notebook; its feelers carefully guide a rolling ladder along the growing archive.",
          "fishMarkup": "[excited] В твоём дневнике уже <emphasis>26 разных недель</emphasis> с собственными заметками. Ты собрал столько наблюдений, что полка задумалась о расширении.",
          "audioText": "В твоём дневнике уже 26 разных недель с собственными заметками. Ты собрал столько наблюдений, что полка задумалась о расширении."
        },
        {
          "id": "reflection.note_weeks:t5",
          "title": "Лень просит абонемент",
          "phrase": "Ты оставил собственные заметки в 52 разных неделях. Личная библиотека открыта — лень просит читательский билет.",
          "imagePrompt": "The notebook-shelled snail has become a mobile library, its open cover forming a checkout counter; a sleepy pillow presents a blank borrowing card while tiny dumbbells queue beside shelves built into the enormous shell.",
          "fishMarkup": "[triumphant] Ты оставил собственные заметки в <emphasis>52 разных неделях</emphasis>. Личная библиотека открыта — <slow>лень просит читательский билет</slow>.",
          "audioText": "Ты оставил собственные заметки в 52 разных неделях. Личная библиотека открыта — лень просит читательский билет."
        }
      ]
    }
  ]
}
